import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { motion, AnimatePresence } from 'framer-motion';
import { FiMessageCircle, FiSearch, FiPlus, FiMoreVertical } from 'react-icons/fi';
import { getChatList, getChatDetails, setCurrentChat } from '../../store/slices/chatSlice';
import { getDoctors } from '../../store/slices/userSlice';
import ChatList from '../../components/Chat/ChatList';
import ChatWindow from '../../components/Chat/ChatWindow';
import DoctorList from '../../components/Chat/DoctorList';
import UserSearch from '../../components/Chat/UserSearch';
import LoadingSpinner from '../../components/UI/LoadingSpinner';

const Chat = () => {
  const { chatId } = useParams();
  const navigate = useNavigate();
  const dispatch = useDispatch();
  
  const { user } = useSelector((state) => state.auth);
  const { chats = [], currentChat, isLoading, error } = useSelector((state) => state.chat || {});
  const { doctors = [], isLoading: doctorLoading } = useSelector((state) => state.user || {});
  
  const [view, setView] = useState('list'); // 'list', 'chat', 'doctors', 'users'
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    // Load chats and doctors
    dispatch(getChatList({ page: 1, limit: 50 }));
    dispatch(getDoctors({ page: 1, limit: 20 }));
  }, [dispatch]);

  useEffect(() => {
    // Load specific chat if chatId is provided
    if (chatId && chatId !== 'new' && chatId !== 'users') {
      dispatch(getChatDetails({ chatId, params: { page: 1, limit: 50 } }));
      setView('chat');
    } else if (chatId === 'new') {
      setView('doctors');
    } else if (chatId === 'users') {
      setView('users');
    } else {
      setView('list');
    }
  }, [chatId, dispatch]);

  const handleChatSelect = (chat) => {
    dispatch(setCurrentChat(chat));
    navigate(`/chat/${chat._id}`);
    setView('chat');
  };

  const handleNewChat = () => {
    navigate('/chat/new');
    setView('doctors');
  };

  const handleFindUsers = () => {
    navigate('/chat/users');
    setView('users');
  };

  const handleUserSelect = (selectedUser) => {
    // Create chat with selected user
    console.log('Creating chat with user:', selectedUser);
    // This would dispatch createChat action with the selected user
    // For now, we'll just navigate back to chat list
    navigate('/chat');
    setView('list');
  };

  const handleBackToList = () => {
    navigate('/chat');
    setView('list');
  };

  const filteredChats = chats.filter(chat => {
    const otherParticipant = chat.participants?.find(p => p._id !== user?._id);
    return otherParticipant?.fullName?.toLowerCase().includes(searchQuery.toLowerCase());
  });

  const filteredDoctors = doctors.filter(doctor => 
    doctor.fullName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    doctor.specialization?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (isLoading && !chats.length) {
    return (
      <div className="h-full flex items-center justify-center">
        <LoadingSpinner size="large" />
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 px-4 py-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            {view === 'chat' && (
              <button
                onClick={handleBackToList}
                className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
              </button>
            )}
            
            <h1 className="text-xl font-semibold text-gray-900">
              {view === 'list' && 'Messages'}
              {view === 'chat' && 'Chat'}
              {view === 'doctors' && 'Find Doctors'}
              {view === 'users' && 'Find Users'}
            </h1>
          </div>

          <div className="flex items-center space-x-2">
            {/* Search */}
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <FiSearch className="h-4 w-4 text-gray-400" />
              </div>
              <input
                type="text"
                placeholder="Search..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* New Chat Button */}
            {view === 'list' && (
              <button
                onClick={handleNewChat}
                className="p-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors"
              >
                <FiPlus className="h-5 w-5" />
              </button>
            )}

            {/* More Options */}
            <button className="p-2 hover:bg-gray-100 rounded-lg transition-colors">
              <FiMoreVertical className="h-5 w-5" />
            </button>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 flex overflow-hidden">
        <AnimatePresence mode="wait">
          {view === 'list' && (
            <motion.div
              key="list"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.3 }}
              className="flex-1"
            >
              <ChatList
                chats={filteredChats}
                onChatSelect={handleChatSelect}
                onNewChat={handleNewChat}
                searchQuery={searchQuery}
              />
            </motion.div>
          )}

          {view === 'doctors' && (
            <motion.div
              key="doctors"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              transition={{ duration: 0.3 }}
              className="flex-1"
            >
              <DoctorList
                doctors={filteredDoctors}
                isLoading={doctorLoading}
                onDoctorSelect={(doctor) => {
                  // Create new chat with doctor
                  // This would dispatch createChat action
                  console.log('Create chat with doctor:', doctor);
                }}
              />
            </motion.div>
          )}

          {view === 'chat' && currentChat && (
            <motion.div
              key="chat"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              transition={{ duration: 0.3 }}
              className="flex-1"
            >
              <ChatWindow chat={currentChat} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 text-sm">
          {error}
        </div>
      )}
    </div>
  );
};

export default Chat;
